-- Five demo exhibition subjects substituted with licensed, visually matched alternatives.
-- Only descriptive metadata: no price/stock/activity/shipping/finance/store changes.
-- Authorized by Oliver2026-10-14; use only Marketplace. Atomic, exact UUIDs, is_demo retained.
begin;
do $exhibition$
declare v_before jsonb; v_after jsonb; v_count int; v_url text;
begin
 select decrypted_secret into strict v_url from vault.decrypted_secrets where name='kora_project_url';
 if rtrim(v_url,'/') is distinct from 'https://mimnotafmfasvwrclxan.supabase.co' then raise exception 'Wrong exhibition project'; end if;
 select count(*) into v_count from public.products where id in ('e7a91cd8-d3a2-4436-986c-71d1d95da813'::uuid,'01a43334-e485-41cc-a12a-c049e933665d'::uuid,'22516bf2-7283-45c1-a3a5-2449797a25db'::uuid,'910cdfb7-9a3e-48e5-bd40-99269aea332a'::uuid,'6209f8ff-aeab-40e3-9168-9528a30ca55d'::uuid) and is_demo and moderation_status='published';
 if v_count<>5 then raise exception 'Expected five published demo products'; end if;
 if not exists(select 1 from public.products where id='e7a91cd8-d3a2-4436-986c-71d1d95da813' and title in ('UGREEN Nexode cargador GaN 65 W','Samsung cargador USB-C 45 W · EP-T4510')) then raise exception 'Unexpected demo subject'; end if;
 if not exists(select 1 from public.products where id='01a43334-e485-41cc-a12a-c049e933665d' and title in ('UGREEN Nexode power bank 20.000 mAh','Anker PowerCore 10.000 mAh')) then raise exception 'Unexpected demo subject'; end if;
 if not exists(select 1 from public.products where id='22516bf2-7283-45c1-a3a5-2449797a25db' and title in ('UGREEN cable USB-C a USB-C','UGREEN lector SD · USB-A y USB-C')) then raise exception 'Unexpected demo subject'; end if;
 if not exists(select 1 from public.products where id='910cdfb7-9a3e-48e5-bd40-99269aea332a' and title in ('UGREEN Revodok hub USB-C 6 en 1','StarTech.com hub USB 3.0 de 7 puertos · ST7300U3M')) then raise exception 'Unexpected demo subject'; end if;
 if not exists(select 1 from public.products where id='6209f8ff-aeab-40e3-9168-9528a30ca55d' and title in ('UGREEN Nexode cargador GaN 30 W','UGREEN cargador de carro 30 W · 25845')) then raise exception 'Unexpected demo subject'; end if;
 perform 1 from public.product_variants where product_id in ('e7a91cd8-d3a2-4436-986c-71d1d95da813'::uuid,'01a43334-e485-41cc-a12a-c049e933665d'::uuid,'22516bf2-7283-45c1-a3a5-2449797a25db'::uuid,'910cdfb7-9a3e-48e5-bd40-99269aea332a'::uuid,'6209f8ff-aeab-40e3-9168-9528a30ca55d'::uuid) for update;
 select jsonb_agg(jsonb_build_object('id',id,'product_id',product_id,'price_usd',price_usd,'stock',stock,'active',active) order by id) into v_before from public.product_variants where product_id in ('e7a91cd8-d3a2-4436-986c-71d1d95da813'::uuid,'01a43334-e485-41cc-a12a-c049e933665d'::uuid,'22516bf2-7283-45c1-a3a5-2449797a25db'::uuid,'910cdfb7-9a3e-48e5-bd40-99269aea332a'::uuid,'6209f8ff-aeab-40e3-9168-9528a30ca55d'::uuid);
 insert into public.brands(slug,name) values ('samsung','Samsung'),('anker','Anker'),('startech','StarTech.com') on conflict(slug) do nothing;
 update public.products set title='Samsung cargador USB-C 45 W · EP-T4510', subtitle='Negro', description='Cargador de pared Samsung EP-T4510 negro de45W. La fotografía principal incluye un cable USB-C; elige la presentación con cable o solo cargador.', highlights=array['EP-T4510','45 W','USB-C']::text[], option_names=array['Presentación']::text[], brand_id=(select id from public.brands where slug='samsung') where id='e7a91cd8-d3a2-4436-986c-71d1d95da813' and is_demo;
 update public.products set title='Anker PowerCore 10.000 mAh', subtitle='Negro', description='Batería externa Anker PowerCore10000mAh negra, con puerto de salida USB-A. El cable Lightning de la fotografía acompaña la presentación mostrada.', highlights=array['PowerCore 10000','USB-A','Negro']::text[], option_names=array['Color']::text[], brand_id=(select id from public.brands where slug='anker') where id='01a43334-e485-41cc-a12a-c049e933665d' and is_demo;
 update public.products set title='UGREEN lector SD · USB-A y USB-C', subtitle='Gris y negro', description='Lector de tarjetas SD UGREEN gris y negro con conectores USB-A y USB-C. Elige el tipo de conexión que quieres probar.', highlights=array['Tarjetas SD','USB-A y USB-C','Gris y negro']::text[], option_names=array['Conexión']::text[], brand_id=(select id from public.brands where slug='ugreen') where id='22516bf2-7283-45c1-a3a5-2449797a25db' and is_demo;
 update public.products set title='StarTech.com hub USB 3.0 de 7 puertos · ST7300U3M', subtitle='Negro', description='Hub StarTech.com ST7300U3M negro de7 puertos USB3.0, con alimentación externa. La fotografía muestra el hub, sus cables, adaptador de corriente y documentación.', highlights=array['ST7300U3M','7 puertos USB 3.0','Alimentación externa']::text[], option_names=array['Color']::text[], brand_id=(select id from public.brands where slug='startech') where id='910cdfb7-9a3e-48e5-bd40-99269aea332a' and is_demo;
 update public.products set title='UGREEN cargador de carro 30 W · 25845', subtitle='Negro', description='Cargador de carro UGREEN25845 negro de30W, con puertoUSB-C y puertoUSB-A.', highlights=array['25845','30 W','USB-C y USB-A']::text[], option_names=array['Color']::text[], brand_id=(select id from public.brands where slug='ugreen') where id='6209f8ff-aeab-40e3-9168-9528a30ca55d' and is_demo;
 update public.product_variants set title='Con cable · Negro', options='{"Presentación": "Con cable", "Color": "Negro"}'::jsonb, sku='DEMO-SAMSUNG-EP-T4510-CABLE' where id='930576a5-751f-4f67-904e-19f21b2e969b' and product_id in ('e7a91cd8-d3a2-4436-986c-71d1d95da813'::uuid,'01a43334-e485-41cc-a12a-c049e933665d'::uuid,'22516bf2-7283-45c1-a3a5-2449797a25db'::uuid,'910cdfb7-9a3e-48e5-bd40-99269aea332a'::uuid,'6209f8ff-aeab-40e3-9168-9528a30ca55d'::uuid);
 if not found then raise exception 'Expected demo variant missing'; end if;
 update public.product_variants set title='Solo cargador · Negro', options='{"Presentación": "Solo cargador", "Color": "Negro"}'::jsonb, sku='DEMO-SAMSUNG-EP-T4510-SOLO' where id='03c25cc2-2186-466f-a3a5-0f0201dfad81' and product_id in ('e7a91cd8-d3a2-4436-986c-71d1d95da813'::uuid,'01a43334-e485-41cc-a12a-c049e933665d'::uuid,'22516bf2-7283-45c1-a3a5-2449797a25db'::uuid,'910cdfb7-9a3e-48e5-bd40-99269aea332a'::uuid,'6209f8ff-aeab-40e3-9168-9528a30ca55d'::uuid);
 if not found then raise exception 'Expected demo variant missing'; end if;
 update public.product_variants set title='Negro', options='{"Color": "Negro"}'::jsonb, sku='DEMO-ANKER-POWERCORE-10000' where id='78a639c7-0cb2-403c-9339-d4bcfd70fcf4' and product_id in ('e7a91cd8-d3a2-4436-986c-71d1d95da813'::uuid,'01a43334-e485-41cc-a12a-c049e933665d'::uuid,'22516bf2-7283-45c1-a3a5-2449797a25db'::uuid,'910cdfb7-9a3e-48e5-bd40-99269aea332a'::uuid,'6209f8ff-aeab-40e3-9168-9528a30ca55d'::uuid);
 if not found then raise exception 'Expected demo variant missing'; end if;
 update public.product_variants set title='USB-A', options='{"Conexión": "USB-A"}'::jsonb, sku='DEMO-UGREEN-LECTOR-SD-A' where id='e3344155-4b5e-48a2-8022-7c4adc23b209' and product_id in ('e7a91cd8-d3a2-4436-986c-71d1d95da813'::uuid,'01a43334-e485-41cc-a12a-c049e933665d'::uuid,'22516bf2-7283-45c1-a3a5-2449797a25db'::uuid,'910cdfb7-9a3e-48e5-bd40-99269aea332a'::uuid,'6209f8ff-aeab-40e3-9168-9528a30ca55d'::uuid);
 if not found then raise exception 'Expected demo variant missing'; end if;
 update public.product_variants set title='USB-C', options='{"Conexión": "USB-C"}'::jsonb, sku='DEMO-UGREEN-LECTOR-SD-C' where id='c0e852b0-feaf-44be-a62f-41563c438fa4' and product_id in ('e7a91cd8-d3a2-4436-986c-71d1d95da813'::uuid,'01a43334-e485-41cc-a12a-c049e933665d'::uuid,'22516bf2-7283-45c1-a3a5-2449797a25db'::uuid,'910cdfb7-9a3e-48e5-bd40-99269aea332a'::uuid,'6209f8ff-aeab-40e3-9168-9528a30ca55d'::uuid);
 if not found then raise exception 'Expected demo variant missing'; end if;
 update public.product_variants set title='Negro', options='{"Color": "Negro"}'::jsonb, sku='DEMO-STARTECH-ST7300U3M' where id='81f5e2c5-3f39-4181-82de-b3ab4c45495a' and product_id in ('e7a91cd8-d3a2-4436-986c-71d1d95da813'::uuid,'01a43334-e485-41cc-a12a-c049e933665d'::uuid,'22516bf2-7283-45c1-a3a5-2449797a25db'::uuid,'910cdfb7-9a3e-48e5-bd40-99269aea332a'::uuid,'6209f8ff-aeab-40e3-9168-9528a30ca55d'::uuid);
 if not found then raise exception 'Expected demo variant missing'; end if;
 update public.product_variants set title='Negro', options='{"Color": "Negro"}'::jsonb, sku='DEMO-UGREEN-CAR-25845' where id='2d147d94-cbde-49e5-aa63-95e0bc942771' and product_id in ('e7a91cd8-d3a2-4436-986c-71d1d95da813'::uuid,'01a43334-e485-41cc-a12a-c049e933665d'::uuid,'22516bf2-7283-45c1-a3a5-2449797a25db'::uuid,'910cdfb7-9a3e-48e5-bd40-99269aea332a'::uuid,'6209f8ff-aeab-40e3-9168-9528a30ca55d'::uuid);
 if not found then raise exception 'Expected demo variant missing'; end if;
 update public.product_images set alt='Samsung cargador USB-C 45 W · EP-T4510' where product_id='e7a91cd8-d3a2-4436-986c-71d1d95da813' and path like 'demo/%';
 update public.product_images set alt='Anker PowerCore 10.000 mAh' where product_id='01a43334-e485-41cc-a12a-c049e933665d' and path like 'demo/%';
 update public.product_images set alt='UGREEN lector SD · USB-A y USB-C' where product_id='22516bf2-7283-45c1-a3a5-2449797a25db' and path like 'demo/%';
 update public.product_images set alt='StarTech.com hub USB 3.0 de 7 puertos · ST7300U3M' where product_id='910cdfb7-9a3e-48e5-bd40-99269aea332a' and path like 'demo/%';
 update public.product_images set alt='UGREEN cargador de carro 30 W · 25845' where product_id='6209f8ff-aeab-40e3-9168-9528a30ca55d' and path like 'demo/%';
 select jsonb_agg(jsonb_build_object('id',id,'product_id',product_id,'price_usd',price_usd,'stock',stock,'active',active) order by id) into v_after from public.product_variants where product_id in ('e7a91cd8-d3a2-4436-986c-71d1d95da813'::uuid,'01a43334-e485-41cc-a12a-c049e933665d'::uuid,'22516bf2-7283-45c1-a3a5-2449797a25db'::uuid,'910cdfb7-9a3e-48e5-bd40-99269aea332a'::uuid,'6209f8ff-aeab-40e3-9168-9528a30ca55d'::uuid);
 if v_before is distinct from v_after then raise exception 'Financial/stock fields changed; rolling back'; end if;
end $exhibition$;
commit;
select id,title,is_demo from public.products where id in ('e7a91cd8-d3a2-4436-986c-71d1d95da813'::uuid,'01a43334-e485-41cc-a12a-c049e933665d'::uuid,'22516bf2-7283-45c1-a3a5-2449797a25db'::uuid,'910cdfb7-9a3e-48e5-bd40-99269aea332a'::uuid,'6209f8ff-aeab-40e3-9168-9528a30ca55d'::uuid) order by id;
